package com.nextrade.domain.risk; import com.nextrade.common.enumtype.*; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; import java.time.*;
public record CashReservation(ReservationId id,OrderId orderId,UserId userId,Money amount,ReservationStatus status,Instant createdAt,Instant updatedAt){public CashReservation activate(){return new CashReservation(id,orderId,userId,amount,ReservationStatus.ACTIVE,createdAt,Instant.now());}public CashReservation release(){return new CashReservation(id,orderId,userId,amount,ReservationStatus.RELEASED,createdAt,Instant.now());}public CashReservation consume(){return new CashReservation(id,orderId,userId,amount,ReservationStatus.CONSUMED,createdAt,Instant.now());}}
